// Readable connection names live outside the physical package, not on an opaque plate.
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function labelSide(p,d){if(p.side)return p.side;if(p.y>d.height*.72)return'bottom';if(p.y<d.height*.2)return'top';return p.x<d.width/2?'left':'right';}
export function pinLabelLayout(p,d){const side=labelSide(p,d),row=d.pinDefs.filter(q=>q.connectable!==false&&labelSide(q,d)===side),pitch=Math.min(...row.filter(q=>q!==p&&q.id!==p.id).map(q=>Math.abs(q.x-p.x)).filter(n=>n>0)),angle=pitch<15?70:55;return side==='bottom'?{x:p.x+2,y:p.y+14,angle,anchor:'start'}:side==='top'?{x:p.x+2,y:p.y-12,angle:-angle,anchor:'start'}:side==='left'?{x:p.x-9,y:p.y+3.2,angle:0,anchor:'end'}:{x:p.x+9,y:p.y+3.2,angle:0,anchor:'start'};}
export const hasPinLabels=c=>!['board','breadboard','netLabel','rfidCard'].includes(c.type);
export function pinCaptionY(c,d){if(!hasPinLabels(c))return d.height+16;const bottom=d.pinDefs.filter(p=>labelSide(p,d)==='bottom');return Math.max(d.height+20,...bottom.map(p=>p.y+30+p.id.length*6*.95));}
export function pinLabels(c,d){if(!hasPinLabels(c))return '';return '<g class="readable-pin-labels" pointer-events="none" aria-hidden="true">'+d.pinDefs.filter(p=>p.connectable!==false).map(p=>{const l=pinLabelLayout(p,d),side=labelSide(p,d),tx=side==='left'?p.x-5:side==='right'?p.x+5:p.x,ty=side==='top'?p.y-5:side==='bottom'?p.y+5:p.y,fill=/^(?:VCC|VDD|3V3|5V|VMOT|VM|A)$/.test(p.id)?'#ffe2af':p.id.startsWith('GND')||p.id==='K'?'#cbd8e3':'#f4f8fc';return `<path d="M${p.x} ${p.y}L${tx} ${ty}" fill="none" stroke="#b5c6d2" stroke-width=".8"/><text data-readable-pin="${esc(c.id+':'+p.id)}" x="${l.x}" y="${l.y}" transform="rotate(${l.angle} ${l.x} ${l.y})" text-anchor="${l.anchor}" fill="${fill}" stroke="#111d29" stroke-width="2.6" paint-order="stroke" stroke-linejoin="round" font-family="Consolas,monospace" font-size="10" font-weight="600">${esc(p.id)}</text>`;}).join('')+'</g>';}
